// ============================================================
// CREDO HR-Portal — Erinnerungs-Ergebnis auswerten
// Loggt das Ergebnis und gibt eine Zusammenfassung aus
// ============================================================

try {
  const response = $input.first().json;
  const body = response.body || response;

  const summary = {
    success: body.success || false,
    timestamp: body.timestamp || new Date().toISOString(),
    employeeReminders: body.employeeReminders || 0,
    supervisorReminders: body.supervisorReminders || 0,
    total: body.total || 0,
    errors: body.errors || 0,
    statusCode: response.statusCode || 200
  };

  // Nur E-Mail senden wenn Erinnerungen verschickt wurden
  if (summary.total > 0 || summary.errors > 0) {
    const lines = [
      `Erinnerungs-Bericht vom ${new Date().toLocaleDateString('de-DE')}`,
      '',
      `Mitarbeiter-Erinnerungen: ${summary.employeeReminders}`,
      `Vorgesetzten-Erinnerungen: ${summary.supervisorReminders}`,
      `Gesamt versendet: ${summary.total}`,
      summary.errors > 0 ? `Fehler: ${summary.errors}` : '',
      '',
      'CREDO HR-Portal — Automatischer Bericht'
    ].filter(Boolean).join('\n');

    return [{
      json: {
        sendReport: true,
        to: 'personalbuchhaltung@fes-minden.de',
        subject: `HR-Portal: ${summary.total} Erinnerung(en) versendet${summary.errors > 0 ? ' (' + summary.errors + ' Fehler)' : ''}`,
        html: `<div style="font-family:Calibri,Arial,sans-serif;font-size:14px;color:#2d2d2d;line-height:1.6;"><pre>${lines}</pre></div>`,
        ...summary
      }
    }];
  }

  // Keine Erinnerungen noetig → nichts senden
  return [{ json: { sendReport: false, ...summary } }];

} catch (error) {
  return [{
    json: {
      sendReport: true,
      to: 'personalbuchhaltung@fes-minden.de',
      subject: 'HR-Portal: Fehler beim Erinnerungsversand',
      html: `<div style="font-family:Calibri,Arial,sans-serif;font-size:14px;color:#c00;">Fehler: ${error.message}</div>`,
      error: error.message
    }
  }];
}
